from pathlib import Path
import base64,hashlib,json,subprocess
root=Path('/content/mathvisionkid_recovery_20261026')
payload={'root_paired_decisions_step_000100.json': '', 'build_quality_gate_closure_20261026.py': ''}
for name,encoded in payload.items():
 raw=base64.b64decode(encoded); path=root/name
 if path.exists():
  assert path.read_bytes()==raw, 'refuse changed existing file: '+name
 else: path.write_bytes(raw)
result=subprocess.run([str(root/'venv/bin/python'),str(root/'build_quality_gate_closure_20261026.py'),'--root',str(root),'--decisions',str(root/'root_paired_decisions_step_000100.json'),'--step','100'],capture_output=True,text=True,timeout=30)
print(json.dumps({'returncode':result.returncode,'stdout':result.stdout[-6000:],'stderr':result.stderr[-3000:]}))
assert result.returncode==0
